#!/usr/bin/env python3

import os
import shutil

def cleanup_playwright_artifacts():
    """Clean up Playwright artifacts directories to free up space"""
    base_path = '/tmp'
    removed_count = 0
    total_size = 0

    # Find all playwright-artifacts directories
    for item in os.listdir(base_path):
        if item.startswith('playwright-artifacts-') and os.path.isdir(os.path.join(base_path, item)):
            try:
                # Calculate size before removal
                size = 0
                for dirpath, dirnames, filenames in os.walk(os.path.join(base_path, item)):
                    for filename in filenames:
                        filepath = os.path.join(dirpath, filename)
                        if os.path.exists(filepath):
                            size += os.path.getsize(filepath)

                # Remove the directory
                shutil.rmtree(os.path.join(base_path, item))
                total_size += size
                removed_count += 1
                print(f"Removed {item} ({size} bytes)")
            except Exception as e:
                print(f"Error removing {item}: {e}")

        # Limit the number of directories to remove to avoid taking too long
        if removed_count >= 50:
            break

    print(f"\nCleanup completed. Removed {removed_count} directories.")
    print(f"Approximately freed {total_size / (1024*1024):.2f} MB of space.")

if __name__ == "__main__":
    cleanup_playwright_artifacts()

